// J-02: anything waiting too long reminds the approver, then their manager.
// H-01: value decides who has to look at it at all.
const cfg = $('Config').first().json;
const REMIND_AFTER  = Number(cfg.remind_after_hours);    // nudge the approver
const ESCALATE_AFTER = Number(cfg.escalate_after_hours); // go over their head
const DIRECTOR_THRESHOLD = Number(cfg.director_threshold_aed);

const users = $('Get Users').all().map(u => u.json);
const byName = (name) => {
  const k = String(name || '').trim().toLowerCase();
  if (!k) return null;
  return users.find(u => String(u.full_name || '').toLowerCase() === k ||
                         String(u.username || '').toLowerCase() === k) || null;
};
const director = users.find(u => /director|owner/i.test(String(u.role || '')));

const out = [];
for (const it of $input.all()) {
  const r = it.json;
  const hrs = Number(r.hours_pending);
  const amt = Number(r.amount || 0);
  const bigTicket = amt >= DIRECTOR_THRESHOLD;

  let stage = null;
  if (hrs >= ESCALATE_AFTER) stage = 'escalate';
  else if (hrs >= REMIND_AFTER) stage = 'remind';
  if (!stage) continue;

  const approver = byName(r.approver_name);
  const target = (stage === 'escalate' || bigTicket || !approver)
      ? director : approver;
  if (!target) continue;

  const url = `${cfg.portal_url}/record/${r.form_code}/${r.id}`;
  const head = stage === 'escalate'
      ? `ESCALATED - waiting ${Math.round(hrs)}h`
      : `Waiting ${Math.round(hrs)}h for your approval`;

  out.push({ json: {
    channel: stage === 'escalate' ? 'email,whatsapp,slack' : 'email',
    to_email: target.email,
    slack_channel: 'dharani-approvals',
    subject: `[APPROVAL] ${head} - ${r.subject_txt}`,
    message:
`${head}

Register : ${r.form_title} (${r.form_code})
Document : ${r.doc_no}
Subject  : ${r.subject_txt}
Status   : ${r.status}
${amt > 0 ? 'Value    : AED ' + amt.toLocaleString() + (bigTicket ? '  (above the director threshold)' : '') + '\n' : ''}Approver : ${r.approver_name || 'nobody named on the record'}
Waiting  : ${Math.round(hrs)} hours

Approve or reject it here: ${url}
${stage === 'escalate' ? '\nThis has now been escalated because it passed ' + ESCALATE_AFTER + ' hours unactioned.' : ''}`,
  }});
}
return out;
